/**
 * Patches msg.payload.content with a receiver notice if any files failed.
 * Runs after upload placeholder — metadata.files.failed is complete.
 */
const failed = msg.metadata.files.failed;

if (failed.length === 0) return msg;

const succeeded = msg.metadata.files.items.length;
const total = succeeded + failed.length;
const notice = " [" + failed.length + "/" + total
    + " vedlegg ikke overført. Avsender mottar instruks om alternativ håndtering]";

msg.payload.content = (msg.payload.content || "") + notice;

return msg;

/**
 * Placeholder — WaSOS file upload not yet implemented.
 * All files marked as non-transferable until API support is added.
 */
const utils = global.get("utils");

msg.metadata.files.items.forEach(file => {
    msg.metadata.files.failed.push({
        name: file.name || "unknown file",
        reason: utils.FILE_REASONS.NON_TRANSFERABLE
    });
});

msg.metadata.files.items = [];

return msg;
